import{c as a,Q as o,j as r,m as t}from"./chunks/framework.7r1mYKiJ.js";const u=JSON.parse('{"title":"Scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"features/scenarios.md","filePath":"features/scenarios.md"}'),i={name:"features/scenarios.md"};function l(n,e,s,h,d,c){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h1><p>AetherUHC comes with <strong>80+ fully implemented, highly configurable scenarios</strong> out of the box. Scenarios modify the base rules of Ultra Hardcore to create unique, varied, and exciting gameplay experiences.</p><h2 id="enabling-disabling-scenarios" tabindex="-1">Enabling &amp; Disabling Scenarios <a class="header-anchor" href="#enabling-disabling-scenarios" aria-label="Permalink to &quot;Enabling &amp; Disabling Scenarios&quot;">​</a></h2><p>Scenarios can be toggled via the in-game GUI or commands:</p><ul><li><strong>Command:</strong> <code>/scenarios</code> (Opens the Scenario Manager menu)</li><li><strong>Host Permission required:</strong> <code>aetheruhc.host</code></li></ul><h2 id="full-scenario-list" tabindex="-1">Full Scenario List <a class="header-anchor" href="#full-scenario-list" aria-label="Permalink to &quot;Full Scenario List&quot;">​</a></h2><h3 id="aenabled" tabindex="-1">&amp;aenabled <a class="header-anchor" href="#aenabled" aria-label="Permalink to &quot;&amp;aenabled&quot;">​</a></h3><p>&amp;cdisabled &amp;7.</p><h3 id="actually-monsters-inc" tabindex="-1">ACTUALLY_MONSTERS_INC <a class="header-anchor" href="#actually-monsters-inc" aria-label="Permalink to &quot;ACTUALLY_MONSTERS_INC&quot;">​</a></h3><p>Actually Monsters Inc All doors act as random teleporters to other placed doors.</p><h3 id="anonymous" tabindex="-1">ANONYMOUS <a class="header-anchor" href="#anonymous" aria-label="Permalink to &quot;ANONYMOUS&quot;">​</a></h3><p>Anonymous All players usernames will be hidden so no one knows who they are.</p><h3 id="armageddon" tabindex="-1">ARMAGEDDON <a class="header-anchor" href="#armageddon" aria-label="Permalink to &quot;ARMAGEDDON&quot;">​</a></h3><p>Armageddon Random hazards (TNT, Lava, Potions) fall from the sky.</p><h3 id="assassins" tabindex="-1">ASSASSINS <a class="header-anchor" href="#assassins" aria-label="Permalink to &quot;ASSASSINS&quot;">​</a></h3><p>Assassins Each player is assigned a target at PvP. Only killing your target drops loot. Killing your target assigns you their target.</p><h3 id="astrophobia" tabindex="-1">ASTROPHOBIA <a class="header-anchor" href="#astrophobia" aria-label="Permalink to &quot;ASTROPHOBIA&quot;">​</a></h3><p>Astrophobia Meteors fall creating craters; supercharged creepers and alien skeletons spawn.</p><h3 id="back-packs" tabindex="-1">BACK_PACKS <a class="header-anchor" href="#back-packs" aria-label="Permalink to &quot;BACK_PACKS&quot;">​</a></h3><p>Team Inventory Open your team inventory by typing /teaminventory.</p><h3 id="baldchicken" tabindex="-1">BALDCHICKEN <a class="header-anchor" href="#baldchicken" aria-label="Permalink to &quot;BALDCHICKEN&quot;">​</a></h3><p>Bald Chicken Chicken&#39;s drop no feathers and skeletons drop 3-5 arrows.</p><h3 id="bare-bones" tabindex="-1">BARE_BONES <a class="header-anchor" href="#bare-bones" aria-label="Permalink to &quot;BARE_BONES&quot;">​</a></h3><p>Barebones Enchantment tables/Anvils can&#39;t be crafted or used, Golden apples can&#39;t be crafted either. The Nether is disabled. Players drop 1 Diamond, 2 Golden apples. 32 Arrows and 2 String on death.</p><h3 id="bats" tabindex="-1">BATS <a class="header-anchor" href="#bats" aria-label="Permalink to &quot;BATS&quot;">​</a></h3><p>Bats When a player kills a bat there&#39;s a 95% chance of dropping a Golden Apple and a 5% chance of killing the player.</p><h3 id="benchblitz" tabindex="-1">BENCHBLITZ <a class="header-anchor" href="#benchblitz" aria-label="Permalink to &quot;BENCHBLITZ&quot;">​</a></h3><p>Bench Blitz At the start of the game players will get 1 crafting table they will not be able to create more.</p><h3 id="best-pve" tabindex="-1">BEST_PVE <a class="header-anchor" href="#best-pve" aria-label="Permalink to &quot;BEST_PVE&quot;">​</a></h3><p>Best PvE All players start on a list and gain +1 heart every 10 min. Taking damage removes you; getting a kill re-adds you.</p><h3 id="betazombies" tabindex="-1">BETAZOMBIES <a class="header-anchor" href="#betazombies" aria-label="Permalink to &quot;BETAZOMBIES&quot;">​</a></h3><p>Beta Zombies Zombies when killed will drop feathers.</p><h3 id="better-enchant" tabindex="-1">BETTER_ENCHANT <a class="header-anchor" href="#better-enchant" aria-label="Permalink to &quot;BETTER_ENCHANT&quot;">​</a></h3><p>Better Enchant When you left-click enchant with a book the enchant will be removed from the book.</p><h3 id="big-crack" tabindex="-1">BIG_CRACK <a class="header-anchor" href="#big-crack" aria-label="Permalink to &quot;BIG_CRACK&quot;">​</a></h3><p>Big Crack</p><h3 id="biome-paranoia" tabindex="-1">BIOME_PARANOIA <a class="header-anchor" href="#biome-paranoia" aria-label="Permalink to &quot;BIOME_PARANOIA&quot;">​</a></h3><p>Biome Paranoia Player name tag colors change based on their current biome.</p><h3 id="birds" tabindex="-1">BIRDS <a class="header-anchor" href="#birds" aria-label="Permalink to &quot;BIRDS&quot;">​</a></h3><p>Birds All players can fly!.</p><h3 id="blast-mining" tabindex="-1">BLAST_MINING <a class="header-anchor" href="#blast-mining" aria-label="Permalink to &quot;BLAST_MINING&quot;">​</a></h3><p>Blast Mining 5% chance a creeper spawns (Slowness II 2s), 3% chance primed TNT when mining ores.</p><h3 id="bleedingsweets" tabindex="-1">BLEEDINGSWEETS <a class="header-anchor" href="#bleedingsweets" aria-label="Permalink to &quot;BLEEDINGSWEETS&quot;">​</a></h3><p>Bleeding Sweets When a player dies they drop 1 diamond, 5 gold, 16 arrows and 1 string.</p><h3 id="blood-cycle" tabindex="-1">BLOOD_CYCLE <a class="header-anchor" href="#blood-cycle" aria-label="Permalink to &quot;BLOOD_CYCLE&quot;">​</a></h3><p>Blood Cycle Every 10 minutes, a random ore will deal half a heart of damage when mined.</p><h3 id="blood-diamonds" tabindex="-1">BLOOD_DIAMONDS <a class="header-anchor" href="#blood-diamonds" aria-label="Permalink to &quot;BLOOD_DIAMONDS&quot;">​</a></h3><p>Blood Diamonds When you mine diamond you will lose half a heart.</p><h3 id="blood-enchants" tabindex="-1">BLOOD_ENCHANTS <a class="header-anchor" href="#blood-enchants" aria-label="Permalink to &quot;BLOOD_ENCHANTS&quot;">​</a></h3><p>Blood Enchants You lose half a heart for every level you enchant.</p><h3 id="blood-gold" tabindex="-1">BLOOD_GOLD <a class="header-anchor" href="#blood-gold" aria-label="Permalink to &quot;BLOOD_GOLD&quot;">​</a></h3><p>Blood Gold When you mine gold you will lose half a heart.</p><h3 id="bombers" tabindex="-1">BOMBERS <a class="header-anchor" href="#bombers" aria-label="Permalink to &quot;BOMBERS&quot;">​</a></h3><p>Bombers Everyone starts with unbreakable flint and steel and most animals and monsters drop TNT.</p><h3 id="bookception" tabindex="-1">BOOKCEPTION <a class="header-anchor" href="#bookception" aria-label="Permalink to &quot;BOOKCEPTION&quot;">​</a></h3><p>Bookception When a player dies a random enchant book will spawn at their death location.</p><h3 id="bow-fighters" tabindex="-1">BOW_FIGHTERS <a class="header-anchor" href="#bow-fighters" aria-label="Permalink to &quot;BOW_FIGHTERS&quot;">​</a></h3><p>BowFighters Start with an Infinity bow. Swords stronger than wood and axes stronger than stone are uncraftable.</p><h3 id="bow-less" tabindex="-1">BOW_LESS <a class="header-anchor" href="#bow-less" aria-label="Permalink to &quot;BOW_LESS&quot;">​</a></h3><p>Bowless You won&#39;t be able to use bows.</p><h3 id="broadcaster" tabindex="-1">BROADCASTER <a class="header-anchor" href="#broadcaster" aria-label="Permalink to &quot;BROADCASTER&quot;">​</a></h3><p>Broadcaster When you mine gold or diamonds there is 15% of chance that your location will be broadcasted to the server.</p><h3 id="build-uhc" tabindex="-1">BUILD_UHC <a class="header-anchor" href="#build-uhc" aria-label="Permalink to &quot;BUILD_UHC&quot;">​</a></h3><p>Build UHC All the players will get a kit.</p><h3 id="bedrockless" tabindex="-1">Bedrockless <a class="header-anchor" href="#bedrockless" aria-label="Permalink to &quot;Bedrockless&quot;">​</a></h3><p>Removes bedrock from the world making the bottom flat stone.</p><h3 id="carrotcombo" tabindex="-1">CARROTCOMBO <a class="header-anchor" href="#carrotcombo" aria-label="Permalink to &quot;CARROTCOMBO&quot;">​</a></h3><p>Carrot Combo When player&#39;s craft swords they will receive a carrot with an enchantment Wood Sword = Sharpness 2 Carrot. Gold Sword = Sharpness 2 Carrot Stone Sword = Sharpness 3 Carrot Iron Sword = Sharpness 5 Carrot Diamond Sword = Sharpness 6 Carrot</p><h3 id="catseyes" tabindex="-1">CATSEYES <a class="header-anchor" href="#catseyes" aria-label="Permalink to &quot;CATSEYES&quot;">​</a></h3><p>Cats Eyes Everyone starts with night vision.</p><h3 id="chest" tabindex="-1">CHEST <a class="header-anchor" href="#chest" aria-label="Permalink to &quot;CHEST&quot;">​</a></h3><p>Chest When you kill someone their loot will be put in a chest it will not explode.</p><h3 id="children-left-unattended" tabindex="-1">CHILDREN_LEFT_UNATTENDED <a class="header-anchor" href="#children-left-unattended" aria-label="Permalink to &quot;CHILDREN_LEFT_UNATTENDED&quot;">​</a></h3><p>Children Left Unattended When a teammate dies, survivors gain Speed and a tamed wolf.</p><h3 id="chunk-apocalypse" tabindex="-1">CHUNK_APOCALYPSE <a class="header-anchor" href="#chunk-apocalypse" aria-label="Permalink to &quot;CHUNK_APOCALYPSE&quot;">​</a></h3><p>Chunk Apocalypse</p><h3 id="compensation" tabindex="-1">COMPENSATION <a class="header-anchor" href="#compensation" aria-label="Permalink to &quot;COMPENSATION&quot;">​</a></h3><p>Compensation When a teammate dies, their max health is divided among surviving teammates.</p><h3 id="coronavirus" tabindex="-1">CORONAVIRUS <a class="header-anchor" href="#coronavirus" aria-label="Permalink to &quot;CORONAVIRUS&quot;">​</a></h3><p>Coronavirus Every 5 minutes a random player receives the nausea and poison effect for between 5-60 seconds.</p><h3 id="criple" tabindex="-1">CRIPLE <a class="header-anchor" href="#criple" aria-label="Permalink to &quot;CRIPLE&quot;">​</a></h3><p>Cripple If a player takes fall damage they receive slowness for 30 seconds</p><h3 id="cryophobia" tabindex="-1">CRYOPHOBIA <a class="header-anchor" href="#cryophobia" aria-label="Permalink to &quot;CRYOPHOBIA&quot;">​</a></h3><p>Cryophobia Ice slowly floods the world. Winter mobs spawn.</p><h3 id="cut-clean" tabindex="-1">CUT_CLEAN <a class="header-anchor" href="#cut-clean" aria-label="Permalink to &quot;CUT_CLEAN&quot;">​</a></h3><p>CutClean All ores and drops are pre smelted</p><h3 id="damage-dodgers" tabindex="-1">DAMAGE_DODGERS <a class="header-anchor" href="#damage-dodgers" aria-label="Permalink to &quot;DAMAGE_DODGERS&quot;">​</a></h3><p>Damage Dodgers The first 5% of players to take any damage are eliminated.</p><h3 id="diamond-less" tabindex="-1">DIAMOND_LESS <a class="header-anchor" href="#diamond-less" aria-label="Permalink to &quot;DIAMOND_LESS&quot;">​</a></h3><p>Diamondless You won&#39;t be able to mine diamond ore but you will receive one diamond when you kill a player.</p><h3 id="disableoffhand" tabindex="-1">DISABLEOFFHAND <a class="header-anchor" href="#disableoffhand" aria-label="Permalink to &quot;DISABLEOFFHAND&quot;">​</a></h3><p>Disable Offhand &amp;c(1.9+ Only) Players will not be able to use their offhand.</p><h3 id="disableshields" tabindex="-1">DISABLESHIELDS <a class="header-anchor" href="#disableshields" aria-label="Permalink to &quot;DISABLESHIELDS&quot;">​</a></h3><p>Disable Shields &amp;c(1.9+ Only) Players will not be able to use shields. Shields will be removed from inventories on use.</p><h3 id="dnd" tabindex="-1">DND <a class="header-anchor" href="#dnd" aria-label="Permalink to &quot;DND&quot;">​</a></h3><p>Do Not Disturb (DND) Each time a player enters a fight they will be restricted to just fighting that player once they leave combat they may fight others.</p><h3 id="double-drops" tabindex="-1">DOUBLE_DROPS <a class="header-anchor" href="#double-drops" aria-label="Permalink to &quot;DOUBLE_DROPS&quot;">​</a></h3><p>Double Drops When you kill animals/mobs you receive double drops.</p><h3 id="double-exp" tabindex="-1">DOUBLE_EXP <a class="header-anchor" href="#double-exp" aria-label="Permalink to &quot;DOUBLE_EXP&quot;">​</a></h3><p>DoubleExp Mining ores will gain you 2x more exp.</p><h3 id="double-health" tabindex="-1">DOUBLE_HEALTH <a class="header-anchor" href="#double-health" aria-label="Permalink to &quot;DOUBLE_HEALTH&quot;">​</a></h3><p>Double Health You will be able to regenerate up to 20 hearts.</p><h3 id="double-ores" tabindex="-1">DOUBLE_ORES <a class="header-anchor" href="#double-ores" aria-label="Permalink to &quot;DOUBLE_ORES&quot;">​</a></h3><p>Double Ores When you mine ores you receive 2x more of the ore.</p><h3 id="double-or-nothing" tabindex="-1">DOUBLE_OR_NOTHING <a class="header-anchor" href="#double-or-nothing" aria-label="Permalink to &quot;DOUBLE_OR_NOTHING&quot;">​</a></h3><p>Double or Nothing On mine of iron, diamond, or gold ore you have a 50% chance of 2 of the ore dropping or no ores dropping.</p><h3 id="dragon-rush" tabindex="-1">DRAGON_RUSH <a class="header-anchor" href="#dragon-rush" aria-label="Permalink to &quot;DRAGON_RUSH&quot;">​</a></h3><p>Dragon Rush</p><h3 id="dungeoneering" tabindex="-1">Dungeoneering <a class="header-anchor" href="#dungeoneering" aria-label="Permalink to &quot;Dungeoneering&quot;">​</a></h3><p>Massively increases dungeon spawns and reduces ores near surface.</p><h3 id="eclipse-protocol" tabindex="-1">ECLIPSE_PROTOCOL <a class="header-anchor" href="#eclipse-protocol" aria-label="Permalink to &quot;ECLIPSE_PROTOCOL&quot;">​</a></h3><p>Eclipse Protocol At the start of the game players receive Night Vision, Saturation, and Resistance for 13 minutes.</p><h3 id="enable-natural-regen" tabindex="-1">ENABLE_NATURAL_REGEN <a class="header-anchor" href="#enable-natural-regen" aria-label="Permalink to &quot;ENABLE_NATURAL_REGEN&quot;">​</a></h3><p>Enable Natural Regeneration Natural health regeneration is enabled via Spigot gamerules.</p><h3 id="enemy-recon" tabindex="-1">ENEMY_RECON <a class="header-anchor" href="#enemy-recon" aria-label="Permalink to &quot;ENEMY_RECON&quot;">​</a></h3><p>Enemy Recon Kills grant &#39;recon&#39; charges. Use /recon to secretly view an enemy&#39;s inventory.</p><h3 id="everyrose" tabindex="-1">EVERYROSE <a class="header-anchor" href="#everyrose" aria-label="Permalink to &quot;EVERYROSE&quot;">​</a></h3><p>Every Rose Each player will receive a golden chestplate with thorns 3 at the start of the game.</p><h3 id="exposure" tabindex="-1">EXPOSURE <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;EXPOSURE&quot;">​</a></h3><p>Exposure When a player crafts an enchantment table they will be teleported to the surface and given mining fatigue for 1 minute.</p><h3 id="extra-inventory" tabindex="-1">EXTRA_INVENTORY <a class="header-anchor" href="#extra-inventory" aria-label="Permalink to &quot;EXTRA_INVENTORY&quot;">​</a></h3><p>Backbacks Allows players to use /backpack</p><h3 id="fire-less" tabindex="-1">FIRE_LESS <a class="header-anchor" href="#fire-less" aria-label="Permalink to &quot;FIRE_LESS&quot;">​</a></h3><p>Fireless You won&#39;t take fire damage at all.</p><h3 id="flower-power" tabindex="-1">FLOWER_POWER <a class="header-anchor" href="#flower-power" aria-label="Permalink to &quot;FLOWER_POWER&quot;">​</a></h3><p>Flower Power Every time you break a flower it will drop a random item in the game.</p><h3 id="fast-smelting" tabindex="-1">Fast Smelting <a class="header-anchor" href="#fast-smelting" aria-label="Permalink to &quot;Fast Smelting&quot;">​</a></h3><p>Furnaces smelt and burn fuel ~10x faster.</p><h3 id="gap-zap" tabindex="-1">GAP_ZAP <a class="header-anchor" href="#gap-zap" aria-label="Permalink to &quot;GAP_ZAP&quot;">​</a></h3><p>Gap Zap Taking damage while regenerating removes regeneration.</p><h3 id="golden-retriever" tabindex="-1">GOLDEN_RETRIEVER <a class="header-anchor" href="#golden-retriever" aria-label="Permalink to &quot;GOLDEN_RETRIEVER&quot;">​</a></h3><p>Golden Retriever Players drop 1 golden head on death.</p><h3 id="gold-less" tabindex="-1">GOLD_LESS <a class="header-anchor" href="#gold-less" aria-label="Permalink to &quot;GOLD_LESS&quot;">​</a></h3><p>Goldless You won&#39;t be able to mine gold ore but you will receive one gold when you kill a player.</p><h3 id="gone-fishing" tabindex="-1">GONE_FISHING <a class="header-anchor" href="#gone-fishing" aria-label="Permalink to &quot;GONE_FISHING&quot;">​</a></h3><p>Gone Fishing You will get unbreaking 200 and luck of the sea 200 fishing rod along with 64 anvils. Players will not be able to craft enchantment tables.</p><h3 id="go-to-hell" tabindex="-1">GO_TO_HELL <a class="header-anchor" href="#go-to-hell" aria-label="Permalink to &quot;GO_TO_HELL&quot;">​</a></h3><p>Go To Hell After 30 minutes, overworld players take damage every 30s until they enter the Nether.</p><h3 id="grass-explosion" tabindex="-1">GRASS_EXPLOSION <a class="header-anchor" href="#grass-explosion" aria-label="Permalink to &quot;GRASS_EXPLOSION&quot;">​</a></h3><p>Grass Explosion When players walk on grass it will have a 25% chance to explode. NOTE: Will start immediately upon scatter.</p><h3 id="genie" tabindex="-1">Genie <a class="header-anchor" href="#genie" aria-label="Permalink to &quot;Genie&quot;">​</a></h3><p>Each player gets 3 wishes; kill tiers unlock better rewards. Use &amp;e/genie wish &amp;lt;reward&amp;gt;&amp;b.</p><h3 id="half-ores" tabindex="-1">HALF_ORES <a class="header-anchor" href="#half-ores" aria-label="Permalink to &quot;HALF_ORES&quot;">​</a></h3><p>Half Ores Every second ore of each type you mine drops loot.</p><h3 id="hastey-boys" tabindex="-1">HASTEY_BOYS <a class="header-anchor" href="#hastey-boys" aria-label="Permalink to &quot;HASTEY_BOYS&quot;">​</a></h3><p>Hastey Boys When you craft mining tools they will be enchanted with efficiency III.</p><h3 id="hastey-boys-lite" tabindex="-1">HASTEY_BOYS_LITE <a class="header-anchor" href="#hastey-boys-lite" aria-label="Permalink to &quot;HASTEY_BOYS_LITE&quot;">​</a></h3><p>Hastey Boys Lite When you craft mining tools they will be enchanted with efficiency I.</p><h3 id="horse-less" tabindex="-1">HORSE_LESS <a class="header-anchor" href="#horse-less" aria-label="Permalink to &quot;HORSE_LESS&quot;">​</a></h3><p>Horseless You can&#39;t tame horses You can&#39;t tame donkeys.</p><h3 id="hypixel-heads" tabindex="-1">HYPIXEL_HEADS <a class="header-anchor" href="#hypixel-heads" aria-label="Permalink to &quot;HYPIXEL_HEADS&quot;">​</a></h3><p>Hypixel Heads When you right click a head you will get Regeneration III for 4 seconds and Speed II for 20 seconds.</p><h3 id="infinite-enchant" tabindex="-1">INFINITE_ENCHANT <a class="header-anchor" href="#infinite-enchant" aria-label="Permalink to &quot;INFINITE_ENCHANT&quot;">​</a></h3><p>Infinite Enchant You can infinitely enchant, no limitations You will receive: * x64 Enchantment tables * x64 Anvil * x128 Bookshelf and gain 30000 exp levels.</p><h3 id="iron-less" tabindex="-1">IRON_LESS <a class="header-anchor" href="#iron-less" aria-label="Permalink to &quot;IRON_LESS&quot;">​</a></h3><p>Ironless You cannot mine iron You cannot blast mine iron Everytime you kill someone they drop 8 iron ingots.</p><h3 id="killswitch" tabindex="-1">KILLSWITCH <a class="header-anchor" href="#killswitch" aria-label="Permalink to &quot;KILLSWITCH&quot;">​</a></h3><p>Killswitch On kill, killer and victim inventories are swapped.</p><h3 id="kill-reveal" tabindex="-1">KILL_REVEAL <a class="header-anchor" href="#kill-reveal" aria-label="Permalink to &quot;KILL_REVEAL&quot;">​</a></h3><p>Kill Reveal Teams are anonymous until a player secures a kill.</p><h3 id="kings" tabindex="-1">KINGS <a class="header-anchor" href="#kings" aria-label="Permalink to &quot;KINGS&quot;">​</a></h3><p>Kings Each team gets a King with a gold crown. If the King dies, the entire team is eliminated. Requires teams!</p><h3 id="lafs" tabindex="-1">LAFS <a class="header-anchor" href="#lafs" aria-label="Permalink to &quot;LAFS&quot;">​</a></h3><p>Love at First Sight (LAFS) Teams are formed when two unpaired players hit each other — damage is cancelled and they become teammates. Unpaired players cannot hurt each other. Max team sizes apply.</p><h3 id="lifesteal" tabindex="-1">LIFESTEAL <a class="header-anchor" href="#lifesteal" aria-label="Permalink to &quot;LIFESTEAL&quot;">​</a></h3><p>Lifesteal Securing a kill permanently increases your maximum health.</p><h3 id="lightsout" tabindex="-1">LIGHTSOUT <a class="header-anchor" href="#lightsout" aria-label="Permalink to &quot;LIGHTSOUT&quot;">​</a></h3><p>Lights Out Players can not place torches during the game.</p><h3 id="limitations" tabindex="-1">LIMITATIONS <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;LIMITATIONS&quot;">​</a></h3><p>Limitations - Max of diamonds can be mined. - Max of gold can be mined. - Max of iron can be mined.</p><h3 id="limitedp4" tabindex="-1">LIMITEDP4 <a class="header-anchor" href="#limitedp4" aria-label="Permalink to &quot;LIMITEDP4&quot;">​</a></h3><p>Limited P4 Players will only be able to enchant one item with protection 4.</p><h3 id="limited-enchants" tabindex="-1">LIMITED_ENCHANTS <a class="header-anchor" href="#limited-enchants" aria-label="Permalink to &quot;LIMITED_ENCHANTS&quot;">​</a></h3><p>Limited Enchants You cannot craft enchantment tables There are unbreakable enchantment tables at 0,0 and in each quadrants.</p><h3 id="long-shots" tabindex="-1">LONG_SHOTS <a class="header-anchor" href="#long-shots" aria-label="Permalink to &quot;LONG_SHOTS&quot;">​</a></h3><p>Long Shots If you get a shot from more than 50 blocks, you get healed for 1 heart, and do 1.5x the damage.</p><h3 id="luckyroulette" tabindex="-1">LUCKYROULETTE <a class="header-anchor" href="#luckyroulette" aria-label="Permalink to &quot;LUCKYROULETTE&quot;">​</a></h3><p>Lucky Roulette Every 2 minutes players are given a random item.</p><h3 id="lucky-leaves" tabindex="-1">LUCKY_LEAVES <a class="header-anchor" href="#lucky-leaves" aria-label="Permalink to &quot;LUCKY_LEAVES&quot;">​</a></h3><p>Lucky Leaves There is 0.5% that golden apple will drop from a tree.</p><h3 id="loot-crate" tabindex="-1">Loot Crate <a class="header-anchor" href="#loot-crate" aria-label="Permalink to &quot;Loot Crate&quot;">​</a></h3><p>Periodic random loot drops to all players.</p><h3 id="meetup" tabindex="-1">MEETUP <a class="header-anchor" href="#meetup" aria-label="Permalink to &quot;MEETUP&quot;">​</a></h3><p>Meetup At a set time (/config admin) players will no longer be able to mine ores and will be forced to the surface (if under Y 35).</p><h3 id="moles" tabindex="-1">MOLES <a class="header-anchor" href="#moles" aria-label="Permalink to &quot;MOLES&quot;">​</a></h3><p>Moles One person on each team is chosen to be the Mole The Moles are one team and can communicate with each other, trying to take out the other players The normal players try to find out who the mole is on their team and kill them. This scenario requires teams!</p><h3 id="mystery-scenarios" tabindex="-1">MYSTERY_SCENARIOS <a class="header-anchor" href="#mystery-scenarios" aria-label="Permalink to &quot;MYSTERY_SCENARIOS&quot;">​</a></h3><p>Mystery Scenarios Every 10 minutes, non-mystery scenarios are disabled and 2-3 random scenarios are enabled.</p><h3 id="melee-fun" tabindex="-1">Melee Fun <a class="header-anchor" href="#melee-fun" aria-label="Permalink to &quot;Melee Fun&quot;">​</a></h3><p>Removes hit invulnerability between players (classic no hit-delay PvP).</p><h3 id="nightmare-mode" tabindex="-1">NIGHTMARE_MODE <a class="header-anchor" href="#nightmare-mode" aria-label="Permalink to &quot;NIGHTMARE_MODE&quot;">​</a></h3><p>Nightmare Mode PvE is significantly harder. Creepers spawn silverfish, skeletons shoot poison arrows. Zombies and spiders are buffed.</p><h3 id="nineslot" tabindex="-1">NINESLOT <a class="header-anchor" href="#nineslot" aria-label="Permalink to &quot;NINESLOT&quot;">​</a></h3><p>Nine Slots Only nine slots of the players inventories are usable.</p><h3 id="nine-lives" tabindex="-1">NINE_LIVES <a class="header-anchor" href="#nine-lives" aria-label="Permalink to &quot;NINE_LIVES&quot;">​</a></h3><p>9 Lives Players start with 10 hearts. Upon death, lose 1 max heart but respawn. Requires 1.11+</p><h3 id="nodiamondarmor" tabindex="-1">NODIAMONDARMOR <a class="header-anchor" href="#nodiamondarmor" aria-label="Permalink to &quot;NODIAMONDARMOR&quot;">​</a></h3><p>No Diamond Armor Player&#39;s can not craft diamond armor.</p><h3 id="noodlejump" tabindex="-1">NOODLEJUMP <a class="header-anchor" href="#noodlejump" aria-label="Permalink to &quot;NOODLEJUMP&quot;">​</a></h3><p>Noodle Jump At the start of the game players will receive permanent jump boost.</p><h3 id="no-clean" tabindex="-1">NO_CLEAN <a class="header-anchor" href="#no-clean" aria-label="Permalink to &quot;NO_CLEAN&quot;">​</a></h3><p>NoClean When you kill someone you will become undamaged for 20 seconds.</p><h3 id="no-enchant" tabindex="-1">NO_ENCHANT <a class="header-anchor" href="#no-enchant" aria-label="Permalink to &quot;NO_ENCHANT&quot;">​</a></h3><p>NoEnchant You can&#39;t use enchanting tables or anvils.</p><h3 id="no-fall-damage" tabindex="-1">NO_FALL_DAMAGE <a class="header-anchor" href="#no-fall-damage" aria-label="Permalink to &quot;NO_FALL_DAMAGE&quot;">​</a></h3><p>No Fall You won&#39;t take fall damage.</p><h3 id="nuzlocke" tabindex="-1">Nuzlocke <a class="header-anchor" href="#nuzlocke" aria-label="Permalink to &quot;Nuzlocke&quot;">​</a></h3><p>Players are randomly assigned a Pokemon type. Each type gives unique abilities.</p><h3 id="one-hundred-hearts" tabindex="-1">ONE_HUNDRED_HEARTS <a class="header-anchor" href="#one-hundred-hearts" aria-label="Permalink to &quot;ONE_HUNDRED_HEARTS&quot;">​</a></h3><p>100 Hearts All players start with a massive health pool of 100 hearts.</p><h3 id="op-hastey-boys" tabindex="-1">OP_HASTEY_BOYS <a class="header-anchor" href="#op-hastey-boys" aria-label="Permalink to &quot;OP_HASTEY_BOYS&quot;">​</a></h3><p>Hastey Babies When you craft mining tools they will be enchanted with efficiency V.</p><h3 id="old-combat" tabindex="-1">Old Combat <a class="header-anchor" href="#old-combat" aria-label="Permalink to &quot;Old Combat&quot;">​</a></h3><p>Removes 1.9+ combat cooldowns, sweep attacks, and scales weapon damage to 1.8 values.</p><h3 id="passive-monsters" tabindex="-1">PASSIVE_MONSTERS <a class="header-anchor" href="#passive-monsters" aria-label="Permalink to &quot;PASSIVE_MONSTERS&quot;">​</a></h3><p>Passive Monsters Hostile mobs will not target players.</p><h3 id="puppypower" tabindex="-1">PUPPYPOWER <a class="header-anchor" href="#puppypower" aria-label="Permalink to &quot;PUPPYPOWER&quot;">​</a></h3><p>Puppy Power All players will get 64 bones, 64 rotten flesh, and 64 wolf spawn eggs.</p><h3 id="pyro" tabindex="-1">PYRO <a class="header-anchor" href="#pyro" aria-label="Permalink to &quot;PYRO&quot;">​</a></h3><p>Pyro Players will start the game with a flame 1 and fire aspect 1 book.</p><h3 id="pyrophobia" tabindex="-1">PYROPHOBIA <a class="header-anchor" href="#pyrophobia" aria-label="Permalink to &quot;PYROPHOBIA&quot;">​</a></h3><p>Pyrophobia Water becomes obsidian, then lava. Lapis and Redstone become obsidian. Mobs have Fire Resistance.</p><h3 id="raining-tnt" tabindex="-1">RAINING_TNT <a class="header-anchor" href="#raining-tnt" aria-label="Permalink to &quot;RAINING_TNT&quot;">​</a></h3><p>Raining TNT Every minute TNT will rain down on 2 unlucky players. Starts two minutes into the game.</p><h3 id="random" tabindex="-1">RANDOM <a class="header-anchor" href="#random" aria-label="Permalink to &quot;RANDOM&quot;">​</a></h3><p>Random Scenarios Enabling this will cause random scenarios to be enabled! Disable all scenarios with /scenarios off</p><h3 id="randomizer" tabindex="-1">RANDOMIZER <a class="header-anchor" href="#randomizer" aria-label="Permalink to &quot;RANDOMIZER&quot;">​</a></h3><p>Randomizer Each block will drop a random item or material based upon the config settings.</p><h3 id="redvsblue" tabindex="-1">REDVSBLUE <a class="header-anchor" href="#redvsblue" aria-label="Permalink to &quot;REDVSBLUE&quot;">​</a></h3><p>Red vs Blue Two teams (red, blue) will be randomly selected on game start.</p><h3 id="risky-fall" tabindex="-1">RISKY_FALL <a class="header-anchor" href="#risky-fall" aria-label="Permalink to &quot;RISKY_FALL&quot;">​</a></h3><p>Risky Fall Fall damage is a coin toss: 50% chance for 0 damage, 50% chance for double damage.</p><h3 id="rod-less" tabindex="-1">ROD_LESS <a class="header-anchor" href="#rod-less" aria-label="Permalink to &quot;ROD_LESS&quot;">​</a></h3><p>Rodless You won&#39;t be able to use fishing rods.</p><h3 id="safe-loot" tabindex="-1">SAFE_LOOT <a class="header-anchor" href="#safe-loot" aria-label="Permalink to &quot;SAFE_LOOT&quot;">​</a></h3><p>Safe Loot When you kill someone, if TimeBomb is active, only the killer will have access to spawned chest.</p><h3 id="second-chance" tabindex="-1">SECOND_CHANCE <a class="header-anchor" href="#second-chance" aria-label="Permalink to &quot;SECOND_CHANCE&quot;">​</a></h3><p>Second Chance Each player may respawn once after death (not during deathmatch).</p><h3 id="shared-health" tabindex="-1">SHARED_HEALTH <a class="header-anchor" href="#shared-health" aria-label="Permalink to &quot;SHARED_HEALTH&quot;">​</a></h3><p>Shared Health Teammates share one global health pool. Damage to one reduces everyone&#39;s health.</p><h3 id="siphon" tabindex="-1">SIPHON <a class="header-anchor" href="#siphon" aria-label="Permalink to &quot;SIPHON&quot;">​</a></h3><p>Siphon Kills provide a permanent health boost, extra XP levels, and a random enchanted book.</p><h3 id="sky-high" tabindex="-1">SKY_HIGH <a class="header-anchor" href="#sky-high" aria-label="Permalink to &quot;SKY_HIGH&quot;">​</a></h3><p>Skyhigh If your y coordinates are bellow set Sky High Limit you will take 1 heart down every 30 seconds.</p><h3 id="soup" tabindex="-1">SOUP <a class="header-anchor" href="#soup" aria-label="Permalink to &quot;SOUP&quot;">​</a></h3><p>Soup When you right click a soup you regain 3.5 hearts.</p><h3 id="superheors" tabindex="-1">SUPERHEORS <a class="header-anchor" href="#superheors" aria-label="Permalink to &quot;SUPERHEORS&quot;">​</a></h3><p>Superheroes Each player will gain a random special ability includes speed, strength, resistance, jump boost, extra hearts Fall damage is disabled.</p><h3 id="switcheroo" tabindex="-1">SWITCHEROO <a class="header-anchor" href="#switcheroo" aria-label="Permalink to &quot;SWITCHEROO&quot;">​</a></h3><p>Switcheroo Everytime you shoot a player, you switch positions with them.</p><h3 id="sword-less" tabindex="-1">SWORD_LESS <a class="header-anchor" href="#sword-less" aria-label="Permalink to &quot;SWORD_LESS&quot;">​</a></h3><p>Swordless You can&#39;t craft swords.</p><h3 id="slimy-crack" tabindex="-1">Slimy Crack <a class="header-anchor" href="#slimy-crack" aria-label="Permalink to &quot;Slimy Crack&quot;">​</a></h3><p>Bottom-most solid layer is coated in slime blocks.</p><h3 id="three-arrows" tabindex="-1">THREE_ARROWS <a class="header-anchor" href="#three-arrows" aria-label="Permalink to &quot;THREE_ARROWS&quot;">​</a></h3><p>3x Arrows Bows fire three arrows in a spread pattern instead of one.</p><h3 id="timber" tabindex="-1">TIMBER <a class="header-anchor" href="#timber" aria-label="Permalink to &quot;TIMBER&quot;">​</a></h3><p>Timber When you break one log the whole tree will drop down.</p><h3 id="time-bomb" tabindex="-1">TIME_BOMB <a class="header-anchor" href="#time-bomb" aria-label="Permalink to &quot;TIME_BOMB&quot;">​</a></h3><p>Timebomb When you kill someone their loot will be put in a chest which will explode after 30 seconds.</p><h3 id="tracker" tabindex="-1">TRACKER <a class="header-anchor" href="#tracker" aria-label="Permalink to &quot;TRACKER&quot;">​</a></h3><p>Tracker At the start of the game you will receive compass and you will be able to track players.</p><h3 id="tree-drops" tabindex="-1">TREE_DROPS <a class="header-anchor" href="#tree-drops" aria-label="Permalink to &quot;TREE_DROPS&quot;">​</a></h3><p>TreeDrops Gold has a 0.5% chance of dropping from a leaves Diamonds have a 0.1% Feathers have a chance of 10% dropping.</p><h3 id="triple-drops" tabindex="-1">TRIPLE_DROPS <a class="header-anchor" href="#triple-drops" aria-label="Permalink to &quot;TRIPLE_DROPS&quot;">​</a></h3><p>Triple Drops When you kill animals/mobs you receive triple drops.</p><h3 id="triple-exp" tabindex="-1">TRIPLE_EXP <a class="header-anchor" href="#triple-exp" aria-label="Permalink to &quot;TRIPLE_EXP&quot;">​</a></h3><p>TripleExp Mining ores will gain you 3x more exp.</p><h3 id="triple-ores" tabindex="-1">TRIPLE_ORES <a class="header-anchor" href="#triple-ores" aria-label="Permalink to &quot;TRIPLE_ORES&quot;">​</a></h3><p>Triple Ores When you mine ores you receive 3x more of the ore.</p><h3 id="underground-parallel" tabindex="-1">UNDERGROUND_PARALLEL <a class="header-anchor" href="#underground-parallel" aria-label="Permalink to &quot;UNDERGROUND_PARALLEL&quot;">​</a></h3><p>Underground Parallel</p><h3 id="upside-down-recipes" tabindex="-1">UPSIDE_DOWN_RECIPES <a class="header-anchor" href="#upside-down-recipes" aria-label="Permalink to &quot;UPSIDE_DOWN_RECIPES&quot;">​</a></h3><p>Upside Down Recipes All standard crafting recipes are vertically mirrored.</p><h3 id="veinminer" tabindex="-1">VEINMINER <a class="header-anchor" href="#veinminer" aria-label="Permalink to &quot;VEINMINER&quot;">​</a></h3><p>Vein Miner When players mine blocks any of the same type will break in a chain reaction if they are crouched.</p><h3 id="vengeful-spirits" tabindex="-1">Vengeful Spirits <a class="header-anchor" href="#vengeful-spirits" aria-label="Permalink to &quot;Vengeful Spirits&quot;">​</a></h3><p>On death spawn a ghast; killing it drops the player&#39;s head. Name tags on mobs are disabled.</p><h3 id="web-cage" tabindex="-1">WEB_CAGE <a class="header-anchor" href="#web-cage" aria-label="Permalink to &quot;WEB_CAGE&quot;">​</a></h3><p>Webcage When you kill a player a sphere of cobwebs surrounds you.</p><h3 id="web-limit" tabindex="-1">WEB_LIMIT <a class="header-anchor" href="#web-limit" aria-label="Permalink to &quot;WEB_LIMIT&quot;">​</a></h3><p>Web Limit Players will be limited to having 8 cobwebs in their inventory at one time.</p><h3 id="woodlife" tabindex="-1">WOODLIFE <a class="header-anchor" href="#woodlife" aria-label="Permalink to &quot;WOODLIFE&quot;">​</a></h3><p>Wood Life When players mine coal ore it will not give them anything.</p><h3 id="zombies" tabindex="-1">ZOMBIES <a class="header-anchor" href="#zombies" aria-label="Permalink to &quot;ZOMBIES&quot;">​</a></h3><p>Zombies When a player dies a zombie will be spawned on their death location.</p>',286)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
